<?php
$students=safeRun($pdo,"SELECT s.*,u.full_name,u.email,u.phone,IF(s.supervisor_id=?,'confirmed','awaiting') assignment_status
FROM students s JOIN users u ON u.id=s.user_id
WHERE s.semester_id=? AND (s.supervisor_id=? OR EXISTS(
 SELECT 1 FROM supervisor_requests sr WHERE sr.student_id=s.id AND sr.supervisor_id=? AND sr.semester_id=s.semester_id AND sr.status='accepted' AND sr.coordinator_status='pending'
)) ORDER BY u.full_name",[$lecturerId,$currentSemesterId,$lecturerId,$lecturerId])->fetchAll();
?>
<div class="row g-3"><?php foreach($students as $s):
$cats=(int)safeRun($pdo,'SELECT COUNT(*) c FROM submission_categories WHERE programme_type=? AND (semester_id IS NULL OR semester_id=?)',[$s['programme_type'],$currentSemesterId])->fetch()['c'];
$accepted=(int)safeRun($pdo,"SELECT COUNT(*) c FROM submissions sub WHERE sub.student_id=? AND sub.semester_id=? AND sub.status='approved' AND sub.id=(SELECT MAX(latest.id) FROM submissions latest WHERE latest.student_id=sub.student_id AND latest.category_id=sub.category_id AND latest.semester_id=sub.semester_id)",[$s['id'],$s['semester_id']])->fetch()['c'];
$progress=$cats?min(100,round($accepted/$cats*100)):0;
$subs=safeRun($pdo,"SELECT sub.*,sc.name cat_name,sr.status my_review_status,sr.remarks my_review_remarks FROM submissions sub JOIN submission_categories sc ON sc.id=sub.category_id LEFT JOIN submission_reviews sr ON sr.submission_id=sub.id AND sr.reviewer_role='supervisor' WHERE sub.student_id=? AND sub.semester_id=? AND sub.id=(SELECT MAX(latest.id) FROM submissions latest WHERE latest.student_id=sub.student_id AND latest.category_id=sub.category_id AND latest.semester_id=sub.semester_id) ORDER BY sub.uploaded_at DESC",[$s['id'],$s['semester_id']])->fetchAll(); ?>
<div class="col-lg-6"><div class="card-fy h-100"><div class="d-flex align-items-center gap-3 mb-3"><div class="user-avatar" style="width:44px;height:44px"><?= e(strtoupper(substr($s['full_name'],0,1))) ?></div><div class="flex-grow-1"><strong><?= e($s['full_name']) ?></strong><div class="small text-muted"><?= e($s['matric_number']) ?> · <?= programmeTypeLabel($s['programme_type']) ?></div><span class="badge-fy <?= $s['assignment_status']==='confirmed'?'badge-success':'badge-warning' ?> mt-1"><?= $s['assignment_status']==='confirmed'?'Confirmed Student':'Awaiting Coordinator' ?></span></div><a class="btn-fy-outline btn-sm" href="mailto:<?= e($s['email']) ?>">Email</a></div><div class="small text-muted mb-2"><?= e($s['project_title']?:'No project title') ?></div><div class="d-flex justify-content-between small"><span>Accepted requirements</span><strong><?= $accepted ?>/<?= $cats ?> (<?= $progress ?>%)</strong></div><div class="progress-fy mb-3"><div style="width:<?= $progress ?>%;background:#16A34A"></div></div>
<?php foreach($subs as $sub): $displayStatus=$sub['my_review_status']?:$sub['status']; ?><div class="border-top py-2"><div class="d-flex justify-content-between"><div><strong class="small"><?= e($sub['cat_name']) ?></strong><div class="small text-muted"><?= e($sub['file_name']) ?> · <?= timeAgo($sub['uploaded_at']) ?></div></div><span class="badge-fy badge-<?= statusBadgeColor($displayStatus) ?>"><?= e(submissionStatusLabel($displayStatus)) ?></span></div><div class="d-flex gap-2 mt-2"><a target="_blank" class="btn-fy-outline btn-sm" href="<?= e(secureFileUrl((int)$sub['id'],'submission')) ?>">View</a><?php if($sub['google_doc_link']): ?><a target="_blank" rel="noopener" class="btn-fy-outline btn-sm" href="<?= e($sub['google_doc_link']) ?>">Google Doc</a><?php endif; ?><button class="btn-fy-outline btn-sm" data-bs-toggle="modal" data-bs-target="#review<?= $sub['id'] ?>">Review</button></div></div>
<div class="modal fade" id="review<?= $sub['id'] ?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content" style="border-radius:18px"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="review_submission"><input type="hidden" name="submission_id" value="<?= $sub['id'] ?>"><div class="modal-header"><h6 class="modal-title">Supervisor Review</h6><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label small fw-semibold">Decision</label><select name="sub_status" class="form-control-fy w-100 mb-3"><option value="under_review" <?= $sub['my_review_status']==='under_review'?'selected':'' ?>>Under Review</option><option value="approved" <?= $sub['my_review_status']==='approved'?'selected':'' ?>>Accepted</option><option value="rejected" <?= $sub['my_review_status']==='rejected'?'selected':'' ?>>Rejected</option></select><label class="form-label small fw-semibold">Remarks</label><textarea name="remarks" class="form-control-fy w-100" rows="3"><?= e($sub['my_review_remarks']??'') ?></textarea></div><div class="modal-footer"><button class="btn-fy-orange w-100">Save review</button></div></form></div></div></div>
<?php endforeach; ?><?php if(!$subs): ?><p class="small text-muted mb-0">No submissions yet.</p><?php endif; ?></div></div><?php endforeach; ?><?php if(!$students): ?><div class="col-12"><div class="card-fy text-center py-5 text-muted">You have no assigned supervisees.</div></div><?php endif; ?></div>
